    if(request.method==='GET'&&u.pathname==='/api/bookingphotos'&&env.operations)return json(await env.operations.endpoint(env,u));if(request.method==='GET'&&u.pathname==='/api/lexware/clients'&&env.operations)return json(await env.operations.endpoint(env,u));if(request.method==='GET'&&u.pathname==='/api/state')return json(await state(env));
