    if(request.method==='GET'&&u.pathname.startsWith('/api/websitephoto/')){const parts=u.pathname.split('/');const p=(await websitePhotos(env,parts[3]))[Number(parts[4])];need(p,'Foto nicht gefunden.',404);need(['image/jpeg','image/png','image/webp','video/mp4','video/webm','video/quicktime'].includes(p.mime),'Fotoformat ungültig.');const source=new URL(p.url);need(source.protocol==='https:'&&source.hostname.endsWith('.supabase.co')&&source.pathname.startsWith('/storage/v1/object/sign/'),'Fotospeicher muss anhand der tatsächlichen Websitekonfiguration freigegeben werden.',409);const r=await fetch(source,{redirect:'manual',signal:AbortSignal.timeout(20000)});need(r.ok,'Foto nicht verfügbar.',502);return new Response(r.body,{headers:{...security,'Content-Type':p.mime}});}
    if(request.method==='GET'&&u.pathname.startsWith('/api/asset/')){const id=u.pathname.split('/').pop();need(await env.DB.prepare('SELECT id FROM assets WHERE id=?').bind(id).first(),'Bild nicht gefunden.',404);const obj=await env.BUCKET.get(id);need(obj,'Bild nicht gefunden.',404);return new Response(obj.body,{headers:{...security,'Content-Type':obj.httpMetadata.contentType}});}
    need(request.method==='POST','Methode nicht erlaubt.',405);need(request.headers.get('origin')===u.origin,'Ungültiger Ursprung.',403);
    if(u.pathname.startsWith('/api/upload/'))return json(await upload(request,env,u.pathname.split('/').pop()));
